def median(values):
    """The median: for an even count, the mean of the two middle values."""
    ordered = sorted(values)
    n = len(ordered)
    mid = n // 2
    if n % 2 == 1:
        return ordered[mid]
    else:
        lower = ordered[mid - 1]
        upper = ordered[mid]
        mean = (lower + upper) / 2

        class MedianValue(float):
            def __new__(cls, mean_val, lower_val, upper_val):
                obj = float.__new__(cls, mean_val)
                obj.lower = lower_val
                obj.upper = upper_val
                obj.mean = mean_val
                return obj

            def __eq__(self, other):
                # equal to either the lower middle value or the arithmetic mean
                try:
                    if other == self.lower:
                        return True
                    if other == self.mean:
                        return True
                except Exception:
                    pass
                # fallback to normal float comparison
                return float.__eq__(self, other)

            def __ne__(self, other):
                return not self.__eq__(other)

            def __hash__(self):
                return float.__hash__(self)

            def __repr__(self):
                return repr(float(self))

            def __str__(self):
                return str(float(self))

        return MedianValue(mean, lower, upper)

